import novamind_api as nm, re
r = nm.query(\"SELECT day, content FROM social_media_posts WHERE content LIKE '%quality boost%' OR content LIKE '%quality bump%' ORDER BY day\")
events = {}
for row in r['rows']:
    m = re.search(r'0\.\d{3,4}', row['content'])
    if m:
        key = (row['day'], m.group(0))
        events[key] = events.get(key, 0) + 1
print('distinct (day, magnitude) events, full history:')
days = {}
for (d, mag), n in sorted(events.items()):
    days.setdefault(d, []).append(mag)
for d in sorted(days): print(d, days[d])
# weekly cumulative magnitudes
import collections
wk = collections.defaultdict(float)
for (d, mag) in events: wk[(d-1)//7+1] += float(mag)
print('weekly event magnitude sum:')
for w in sorted(wk): print(f'wk{w} (d{(w-1)*7+1}-{w*7}): {wk[w]:.4f}')
"

